def _get_amax(self, inputs):
    """Get amax from buffer or compute it dynamically."""
    if self._use_constant_amax:
        return torch.tensor(torch.finfo(torch.float8_e4m3fn).max, device=inputs.device)
    if hasattr(self, "_amax"):
        amax = self._amax
        # A constant_amax buffer is registered at config time (on CPU) and may not have
        # followed a later `model.to(device)`; align it with the input device on the fly.
        if amax.device != inputs.device:
            amax = amax.to(inputs.device)
    else:
        reduce_axis = quant_utils.convert_quantization_axis_to_reduce_axis(inputs, self._axis)
        amax = quant_utils.reduce_amax(inputs, axis=reduce_axis, keepdims=True).detach()

    amax = amax.detach() if is_torch_export_mode() else amax.data
    return amax

def weight_only_quantize(model: nn.Module):
    """Just quantize the weights of the model."""
    names = module_name_maps(model)
    seen_modules = set()
    for module in names.name_to_module.values():
        if module in seen_modules:
            continue

        if isinstance(module, QuantModule):
            with enable_weight_access_and_writeback(module, model, names):
                for weight, weight_quantizer in module.iter_weights_for_calibration():
                    weight_quantizer(weight)
        seen_modules.add(module)

def enable_stats_collection(model: nn.Module):
    """Enable stats collection for all quantizers in the model."""
    for name, module in model.named_modules():
        if isinstance(module, TensorQuantizer) and not module._disabled:
            if module._use_constant_amax or module._constant_amax is not None:
                # Quantizers with a constant amax use a fixed amax and don't need calibration.
                # Disable quantization during calibration so it doesn't affect other quantizers.
                module.disable_quant()
                continue
            elif module._calibrator is not None:
                module.disable_quant()
                module.enable_calib()
            else:
                module.disable()

def finish_stats_collection(model: nn.Module, method: str | None = None, **kwargs):
    """Finish stats collection for all quantizers in the model."""
    for _, module in model.named_modules():
        if not isinstance(module, TensorQuantizer) or module._disabled:
            continue

        if module._use_constant_amax or module._constant_amax is not None:
            # Re-enable quantization for constant-amax quantizers disabled in enable_stats_collection.
            module.enable_quant()
            continue

        cal = getattr(module, "_calibrator", None)
        if cal and not getattr(module, "_dynamic", False):
            if method == "entropy":
                if cal.compute_amax(method) is not None:
                    module.load_calib_amax("entropy", **kwargs)
            elif cal.compute_amax(**kwargs) is not None:
                module.load_calib_amax(**kwargs)

        if module.bias_calibrator is not None and module.bias_type == "static":
            module.load_calib_bias()

        module.enable_quant()
        module.disable_calib()

def _fake_quant_backward_function(ctx, grad_outputs, num_args=1):
    saved_tensors = ctx.saved_tensors
    if len(saved_tensors) == 0:
        return (grad_outputs,) + (None,) * (num_args - 1)
    inputs, amax = saved_tensors
    return (_fake_tensor_quant_backward(inputs, amax, grad_outputs),) + (None,) * (num_args - 1)

def _save_for_backward_if_needed(ctx, pass_through_bwd, inputs, amax):
    if not pass_through_bwd and amax is not None:
        amax = (
            amax
            if isinstance(amax, torch.Tensor)
            else torch.tensor(amax, device=inputs.device, dtype=inputs.dtype)
        )
        ctx.save_for_backward(inputs, amax)

def backward(ctx, grad_outputs):
    """Implements straight through estimation with clipping."""
    return _fake_quant_backward_function(ctx, grad_outputs, num_args=9)
